(function () {
const WA_NUMBER = '584246027658';
const header = document.getElementById('header');
const toggle = document.getElementById('menuToggle');
const onScroll = () => header.classList.toggle('scrolled', window.scrollY > 40);
onScroll();
window.addEventListener('scroll', onScroll, { passive: true });
toggle.addEventListener('click', () => {
const open = document.body.classList.toggle('menu-open');
toggle.setAttribute('aria-expanded', open);
});
document.querySelectorAll('#nav a').forEach(a =>
a.addEventListener('click', () => {
document.body.classList.remove('menu-open');
toggle.setAttribute('aria-expanded', 'false');
})
);
const animateCount = el => {
const target = parseFloat(el.dataset.count);
const decimals = parseInt(el.dataset.decimals || '0', 10);
const suffix = el.dataset.suffix || '';
const start = performance.now();
const duration = 1600;
const step = now => {
const p = Math.min((now - start) / duration, 1);
const val = target * (1 - Math.pow(1 - p, 3));
el.textContent = val.toFixed(decimals).replace('.', ',') + suffix;
if (p < 1) requestAnimationFrame(step);
};
requestAnimationFrame(step);
};
const io = new IntersectionObserver(entries => {
entries.forEach(entry => {
if (!entry.isIntersecting) return;
entry.target.classList.add('in');
entry.target.querySelectorAll('[data-count]').forEach(animateCount);
io.unobserve(entry.target);
});
}, { threshold: 0.15, rootMargin: '0px 0px -40px 0px' });
document.querySelectorAll('.reveal').forEach(el => io.observe(el));
document.querySelectorAll('.faq-q').forEach(btn => {
btn.addEventListener('click', () => {
const item = btn.parentElement;
const open = !item.classList.contains('open');
document.querySelectorAll('.faq-item.open').forEach(i => {
i.classList.remove('open');
i.querySelector('.faq-q').setAttribute('aria-expanded', 'false');
});
item.classList.toggle('open', open);
btn.setAttribute('aria-expanded', open);
});
});
document.getElementById('contactForm').addEventListener('submit', e => {
e.preventDefault();
const d = new FormData(e.target);
const lines = [
'Hola Mega Dental Plus 👋',
`Nombre: ${d.get('nombre')}`,
d.get('clinica') ? `Consultorio: ${d.get('clinica')}` : null,
`Servicio: ${d.get('servicio')}`,
d.get('mensaje') ? `Mensaje: ${d.get('mensaje')}` : null
].filter(Boolean);
window.open(`https://wa.me/${WA_NUMBER}?text=${encodeURIComponent(lines.join('\n'))}`, '_blank', 'noopener');
});
document.getElementById('year').textContent = new Date().getFullYear();
})();